const setFlagsAudit = `-- name: SetFlagsAudit :execrows
UPDATE flags SET audit_id = ?1, audit_pending = NULL
WHERE flags.id IN (/*SLICE:ids*/?) AND flags.status <> 'open' AND flags.audit_id IS NULL
`

type SetFlagsAuditParams struct {
	AuditID sql.NullInt64
	Ids     []int64
}

// Links closed flags to the audit row that records their closing, in the
// transaction that writes the row, and clears the marker of any that were
// owed it (TKT-01M29CRJ4E). A flag that already has a row keeps it.
func (q *Queries) SetFlagsAudit(ctx context.Context, arg SetFlagsAuditParams) (int64, error) {
	query := setFlagsAudit
	var queryParams []interface{}
	queryParams = append(queryParams, arg.AuditID)
	if len(arg.Ids) > 0 {
		for _, v := range arg.Ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(arg.Ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	result, err := q.db.ExecContext(ctx, query, queryParams...)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const threadsWithPostsBy = `-- name: ThreadsWithPostsBy :many
SELECT pm.thread_id FROM post_meta pm WHERE pm.author_id = ?1
UNION
SELECT t.id FROM threads t WHERE t.author_id = ?1
ORDER BY 1
`

// The threads holding a post by the user, from the projection: every
// thread a suspension's hide or restore has to look in (TKT-01M29CP2QK).
// The thread's own author is taken too, since CreateThread projects its
// first post before it answers.
func (q *Queries) ThreadsWithPostsBy(ctx context.Context, userID int64) ([]int64, error) {
	rows, err := q.db.QueryContext(ctx, threadsWithPostsBy, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var thread_id int64
		if err := rows.Scan(&thread_id); err != nil {
			return nil, err
		}
		items = append(items, thread_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
